import{_ as u,a0 as l,w as e,s as p,I as s,x as t,a1 as a,A as o,ao as m}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const x=JSON.parse('{"title":"如何在 Ubuntu 上安装 Cinnamon 桌面环境 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 上安装 Cinnamon 桌面环境 | LCTT (201809) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 上安装 Cinnamon 桌面环境 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 上安装 Cinnamon 桌面环境 | LCTT (201809) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201809/20140805 How to Install Cinnamon Desktop on Ubuntu","title":"如何在 Ubuntu 上安装 Cinnamon 桌面环境","tag":"201809","desc":""},"relativePath":"201809/20140805 How to Install Cinnamon Desktop on Ubuntu.md","filePath":"[post].md"}'),r={name:"201809/20140805 How to Install Cinnamon Desktop on Ubuntu.md"};function d(b,n,C,g,f,h){const i=l("Link");return e(),p("div",null,[n[27]||(n[27]=s("h1",{id:"如何在-ubuntu-上安装-cinnamon-桌面环境",tabindex:"-1"},[t("如何在 Ubuntu 上安装 Cinnamon 桌面环境 "),s("a",{class:"header-anchor",href:"#如何在-ubuntu-上安装-cinnamon-桌面环境","aria-label":"Permalink to “如何在 Ubuntu 上安装 Cinnamon 桌面环境”"},"​")],-1)),n[28]||(n[28]=s("blockquote",null,[s("p",null,"这篇教程将会为你展示如何在 Ubuntu 上安装 Cinnamon 桌面环境。")],-1)),s("p",null,[a(i,{href:"http://cinnamon.linuxmint.com/"},{default:o(()=>[...n[0]||(n[0]=[t("Cinnamon",-1)])]),_:1}),n[3]||(n[3]=t(" 是 ",-1)),a(i,{href:"http://www.linuxmint.com/"},{default:o(()=>[...n[1]||(n[1]=[t("Linux Mint",-1)])]),_:1}),n[4]||(n[4]=t(" 的默认桌面环境。不同于 Ubuntu 的 Unity 桌面环境，Cinnamon 是一个更加传统而优雅的桌面环境，其带有底部面板和应用菜单。由于 Cinnamon 桌面以及它类 Windows 的用户界面，许多桌面用户",-1)),a(i,{href:"https://itsfoss.com/linux-mint-vs-ubuntu/"},{default:o(()=>[...n[2]||(n[2]=[t("相较于 Ubuntu 更喜欢 Linux Mint",-1)])]),_:1}),n[5]||(n[5]=t("。",-1))]),s("p",null,[n[7]||(n[7]=t("现在你无需",-1)),a(i,{href:"https://itsfoss.com/guide-install-linux-mint-16-dual-boot-windows/"},{default:o(()=>[...n[6]||(n[6]=[t("安装 Linux Mint",-1)])]),_:1}),n[8]||(n[8]=t(" 就能够体验到 Cinnamon了。在这篇教程，我将会展示给你如何在 Ubuntu 18.04，16.04 和 14.04 上安装 Cinnamon。",-1))]),n[29]||(n[29]=m(`<p>在 Ubuntu 上安装 Cinnamon 之前，有一些事情需要你注意。有时候，安装的额外桌面环境可能会与你当前的桌面环境有冲突。可能导致会话、应用程序或功能等的崩溃。这就是为什么你需要在做这个决定时谨慎一点的原因。</p><h3 id="如何在-ubuntu-上安装-cinnamon-桌面环境-1" tabindex="-1">如何在 Ubuntu 上安装 Cinnamon 桌面环境 <a class="header-anchor" href="#如何在-ubuntu-上安装-cinnamon-桌面环境-1" aria-label="Permalink to “如何在 Ubuntu 上安装 Cinnamon 桌面环境”">​</a></h3><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2018/09/install-cinnamon-ubuntu.png" alt="如何在 Ubuntu 上安装 Cinnamon 桌面环境"></p><p>过去有 Cinnamon 团队为 Ubuntu 提供的一系列的官方 PPA，但现在都已经失效了。不过不用担心，还有一个非官方的 PPA，而且它运行的很完美。这个 PPA 里包含了最新的 Cinnamon 版本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo add-apt-repository  </span></span>
<span class="line"><span>ppa:embrosyn/cinnamon  </span></span>
<span class="line"><span>sudo apt update &amp;&amp; sudo apt install cinnamon</span></span></code></pre></div><p>下载的大小大概是 150 MB（如果我没记错的话）。这其中提供的 Nemo（Cinnamon 的文件管理器，基于 Nautilus）和 Cinnamon 控制中心。这些东西提供了一个更加接近于 Linux Mint 的感觉。</p><h3 id="在-ubuntu-上使用-cinnamon-桌面环境" tabindex="-1">在 Ubuntu 上使用 Cinnamon 桌面环境 <a class="header-anchor" href="#在-ubuntu-上使用-cinnamon-桌面环境" aria-label="Permalink to “在 Ubuntu 上使用 Cinnamon 桌面环境”">​</a></h3><p>Cinnamon 安装完成后，退出当前会话，在登录界面，点击用户名旁边的 Ubuntu 符号：</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2014/08/Change_Desktop_Environment_Ubuntu.jpeg" alt=""></p><p>之后，它将会显示所有系统可用的桌面环境。选择 Cinnamon。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2014/08/Install_Cinnamon_Ubuntu.jpeg" alt=""></p><p>现在你应该已经登录到有着 Cinnamon 桌面环境的 Ubuntu 中了。你还可以通过同样的方式再回到 Unity 桌面。这里有一张以 Cinnamon 做为桌面环境的 Ubuntu 桌面截图。</p><p><img src="https://4bds6hergc-flywheel.netdna-ssl.com/wp-content/uploads/2014/08/Cinnamon_Ubuntu_1404.jpeg" alt=""></p><p>看起来是不是像极了 Linux Mint。此外，我并没有发现任何有关 Cinnamon 和 Unity 的兼容性问题。在 Unity 和 Cinnamon 来回切换，它们也依旧工作的很完美。</p><h4 id="从-ubuntu-卸载-cinnamon" tabindex="-1">从 Ubuntu 卸载 Cinnamon <a class="header-anchor" href="#从-ubuntu-卸载-cinnamon" aria-label="Permalink to “从 Ubuntu 卸载 Cinnamon”">​</a></h4><p>如果你想卸载 Cinnamon，可以使用 PPA Purge 来完成。首先安装 PPA Purge：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install ppa-purge</span></span></code></pre></div><p>安装完成之后，使用下面的命令去移除该 PPA：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo ppa-purge ppa:embrosyn/cinnamon</span></span></code></pre></div>`,19)),s("p",null,[n[10]||(n[10]=t("更多的信息，我建议你去阅读 ",-1)),a(i,{href:"https://itsfoss.com/how-to-remove-or-delete-ppas-quick-tip/"},{default:o(()=>[...n[9]||(n[9]=[t("如何从 Linux 移除 PPA",-1)])]),_:1}),n[11]||(n[11]=t(" 这篇文章。",-1))]),n[30]||(n[30]=s("p",null,"我希望这篇文章能够帮助你在 Ubuntu 上安装 Cinnamon。也可以分享一下你使用 Cinnamon 的经验。",-1)),n[31]||(n[31]=s("hr",null,null,-1)),s("p",null,[n[13]||(n[13]=t("via: ",-1)),a(i,{href:"https://itsfoss.com/install-cinnamon-on-ubuntu/"},{default:o(()=>[...n[12]||(n[12]=[t("https://itsfoss.com/install-cinnamon-on-ubuntu/",-1)])]),_:1})]),s("p",null,[n[18]||(n[18]=t("作者：",-1)),a(i,{href:"https://itsfoss.com/author/abhishek/"},{default:o(()=>[...n[14]||(n[14]=[t("Abhishek Prakash",-1)])]),_:1}),n[19]||(n[19]=t(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:o(()=>[...n[15]||(n[15]=[t("lujun9972",-1)])]),_:1}),n[20]||(n[20]=t(" 译者：",-1)),a(i,{href:"https://github.com/dianbanjiu"},{default:o(()=>[...n[16]||(n[16]=[t("dianbanjiu",-1)])]),_:1}),n[21]||(n[21]=t(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:o(()=>[...n[17]||(n[17]=[t("wxy",-1)])]),_:1})]),s("p",null,[n[24]||(n[24]=t("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...n[22]||(n[22]=[t("LCTT",-1)])]),_:1}),n[25]||(n[25]=t(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:o(()=>[...n[23]||(n[23]=[t("Linux中国",-1)])]),_:1}),n[26]||(n[26]=t(" 荣誉推出",-1))])])}const P=u(r,[["render",d]]);export{x as __pageData,P as default};
